    [Fact]
    public async Task ScopedPerformanceMismatch_PublishesFinalSnapshotAndLatchesOnlyNamedDrift()
    {
        TestContext context = CreateWritableContext();
        await context.Runtime.ObserveAsync(CancellationToken.None);
        ConfirmedDeviceState before = context.Runtime.GetStatus().ConfirmedState!;
        context.Device.SuppressConfirmationFor = DeviceSubsystem.Performance;
        context.Device.AfterSetter = subsystem =>
        {
            if (subsystem == DeviceSubsystem.Performance)
            {
                context.Device.ConfirmedState = context.Device.ConfirmedState with
                {
                    Performance = PerformancePreset.Silent,
                };
            }
        };
        int readsBeforeAction = context.Device.StateReadCalls;

        ControlOperationResult result = await context.Runtime.SetPerformanceOverrideAsync(
            new ManualOverride<PerformancePreset>(
                PerformancePreset.Performance,
                OverrideLifetime.Persistent),
            CancellationToken.None);

        Assert.Equal(ControlOperationStatus.Failed, result.Status);
        Assert.NotSame(before, context.Runtime.GetStatus().ConfirmedState);
        Assert.Equal(context.Device.ConfirmedState, context.Runtime.GetStatus().ConfirmedState);
        Assert.Equal(
            [DeviceSubsystem.Performance],
            context.Runtime.GetStatus().ExternalChanges);
        Assert.Equal(1, context.Device.PerformanceSetCalls);
        Assert.Equal(readsBeforeAction + 2, context.Device.StateReadCalls);
    }

    [Fact]
    public async Task ScopedPerformance_AppliedThenIndeterminateUsesFreshThermalReadback()
    {
        TestContext context = CreateWritableContext();
        await context.Runtime.ObserveAsync(CancellationToken.None);
        ConfirmedBatteryState? batteryBeforeAction =
            context.Runtime.GetStatus().ConfirmedState?.Battery;
        LightingSettings? lightingBeforeAction =
            context.Runtime.GetStatus().ConfirmedState?.Lighting;
        context.Device.UseScopedPerformanceFanRead = true;
        context.Device.BeforeQueuedPerformanceFailure = () =>
            context.Device.ConfirmedState = context.Device.ConfirmedState with
            {
                Performance = PerformancePreset.Silent,
                Fans = FanMode.Automatic,
            };
        context.Device.PerformanceFailures.Enqueue(
            new BladeWriteException(
                WriteSubmissionState.Indeterminate,
                "Injected applied-then-indeterminate performance write."));
        int scopedReadsBeforeAction =
            context.Device.PerformanceFanStateReadCalls;

        ControlOperationResult result = await context.Runtime.SetPerformanceOverrideAsync(
            new ManualOverride<PerformancePreset>(
                PerformancePreset.Silent,
                OverrideLifetime.Persistent),
            CancellationToken.None);

        Assert.Equal(ControlOperationStatus.Applied, result.Status);
        Assert.Contains("confirmed by fresh readback", result.Message);
        Assert.Equal(1, context.Device.PerformanceSetCalls);
        Assert.Equal(
            scopedReadsBeforeAction + 2,
            context.Device.PerformanceFanStateReadCalls);
        Assert.Equal(
            PerformancePreset.Silent,
            context.Runtime.GetStatus().ConfirmedState?.Performance);
        Assert.Equal(
            PerformancePreset.Silent,
            context.Runtime.GetStatus().DesiredState.Performance.Value);
        Assert.Equal(
            batteryBeforeAction,
            context.Runtime.GetStatus().ConfirmedState?.Battery);
        Assert.Equal(
            lightingBeforeAction,
            context.Runtime.GetStatus().ConfirmedState?.Lighting);
        Assert.Empty(context.Runtime.GetStatus().ExternalChanges);
        Assert.Empty(context.Runtime.GetStatus().UnconfirmedWrites);
        Assert.False(context.Runtime.GetStatus().WritesBlocked);
    }

    [Fact]
    public async Task ScopedPerformance_ProvenPreSubmissionFailureRetriesOnce()
    {
        List<TimeSpan> retryDelays = [];
        TestContext context = CreateWritableContext(
            transitionRetryDelay: (delay, _) =>
            {
                retryDelays.Add(delay);
                return Task.CompletedTask;
            });
        context.Device.PerformanceFailures.Enqueue(new BladeWriteException(
            WriteSubmissionState.KnownNotApplied,
            BladeWriteFailurePhase.ThermalPreWriteRead,
            "Injected first-session pre-write read failure."));
        int admissionsBefore = context.Provider.TryGetCount;

        ControlOperationResult result = await context.Runtime
            .SetPerformanceConfigurationOverrideAsync(
                new PerformanceOverride(
                    PerformancePreset.Performance,
                    OverrideLifetime.Persistent),
                static () => true,
                CancellationToken.None);

        Assert.Equal(ControlOperationStatus.Applied, result.Status);
        Assert.Equal(2, context.Device.PerformanceSetCalls);
        Assert.Equal(admissionsBefore + 2, context.Provider.TryGetCount);
        Assert.Equal([TimeSpan.FromSeconds(5)], retryDelays);
        Assert.Equal(
            PerformancePreset.Performance,
            context.Runtime.GetStatus().ConfirmedState?.Performance);
    }

