                cancellation.Token);
            await WaitForAsync(
                () => thermal.Context.Runtime.GetStatus().ThermalConvergence?.State
                    == ThermalConvergenceState.Matched);
            cancellation.Cancel();
            try
            {
                await consumer.WaitAsync(TimeSpan.FromSeconds(5));
            }
            catch (OperationCanceledException)
            {
            }
        }

        string ledgerPath = Path.Combine(
            directory,
