        {
            if (replaced.Task.IsCompleted)
            {
                return;
            }

            ThermalConvergenceLoadResult reserved = thermal.Store
                .LoadAsync(CancellationToken.None)
                .GetAwaiter()
                .GetResult();
            if (reserved.State.InFlight is null)
            {
                return;
            }

            journal.Journal = CreatePendingHyperBoostJournal();
