    private sealed record ThermalConvergenceTestContext(
        TestContext Context,
        ThermalConvergenceStateStore Store,
        System.Security.Principal.SecurityIdentifier UserSid);

    private sealed class ThermalTestUserConfigurationRepository(
        string machineRoot,
        ProfileSetValidator validator) : IUserConfigurationRepository
    {
        public async Task<UserConfigurationContext> LoadAsync(
            System.Security.Principal.SecurityIdentifier userSid,
            CancellationToken cancellationToken)
        {
            string userRoot = Path.Combine(machineRoot, "users", userSid.Value);
            var configurationStore = new BatteryConfigurationStore(
                Path.Combine(userRoot, "profiles.json"),
                Path.Combine(userRoot, "battery-preferences.json"),
                Path.Combine(userRoot, "battery-configuration.commit.json"),
                validator);
            var overrideStore = new PersistentOverrideStore(
                Path.Combine(userRoot, "manual-overrides.json"));
            var convergenceStore = new ThermalConvergenceStateStore(
                Path.Combine(userRoot, "thermal-convergence.json"),
                userSid);
            BatteryConfiguration configuration = await configurationStore.LoadAsync(
                cancellationToken);
            PersistentOverrideLoadResult overrides = await overrideStore.LoadAsync(
                cancellationToken);
            ThermalConvergenceLoadResult convergence = await convergenceStore.LoadAsync(
                cancellationToken);
            return new UserConfigurationContext(
                configurationStore,
                overrideStore,
                configuration,
                overrides.Overrides,
                overrides.Disposition,
                overrides.QuarantineReason)
            {
                ThermalConvergenceStore = convergenceStore,
                ThermalConvergence = convergence,
            };
        }
    }

    private TestContext CreateWritableContext(
        IReadOnlyList<string>? conflicts = null,
        string? detectionFailure = null,
        Func<BatteryConfigurationCommitBoundary, CancellationToken, Task>?
            transactionBoundary = null,
        Func<TimeSpan, CancellationToken, Task>? transitionRetryDelay = null,
        PowerSource initialPowerSource = PowerSource.PluggedIn,
        TimeProvider? timeProvider = null,
        IUserConfigurationRepository? userConfigurationRepository = null,
        ProfileSetValidator? profileValidator = null,
        LowPowerGate? lowPowerGate = null)
    {
        TestContext context = CreateContext(
            providerAvailable: true,
            conflicts,
            detectionFailure,
            initialPowerSource,
            transactionBoundary: transactionBoundary,
            transitionRetryDelay: transitionRetryDelay,
            timeProvider: timeProvider,
            userConfigurationRepository: userConfigurationRepository,
            profileValidator: profileValidator,
            lowPowerGate: lowPowerGate);
        context.Device.Capabilities = DeviceCapabilities.SafeTargetDefaults() with
        {
            ChargeLimits = new HashSet<int> { 50, 55, 60, 65, 70, 75, 80 },
            SupportsBatteryProtectionOff = true,
            SupportsTemporaryFullCharge = true,
        };
        ProfileSet defaults = ProfileDefaults.CreateSafeDefaults();
        PowerProfile active = initialPowerSource switch
        {
            PowerSource.Battery => defaults.Battery,
            PowerSource.UsbC => defaults.UsbC,
            _ => defaults.PluggedIn,
        };
        context.Device.ConfirmedState = new ConfirmedDeviceState(
            active.Performance,
            active.Fans,
            ConfirmedBattery(80),
            active.Lighting);
        return context;
    }

    private async Task<TestContext> CreateDeferredPowerTransitionContextAsync(
        bool enableFullChargeBeforeTransition = false,
        TimeProvider? timeProvider = null,
        bool destinationProtectionEnabled = false,
        IUserConfigurationRepository? userConfigurationRepository = null,
        System.Security.Principal.SecurityIdentifier? activeUser = null,
        bool changeLighting = true)
    {
        PowerSource initialPowerSource = enableFullChargeBeforeTransition
            ? PowerSource.PluggedIn
            : PowerSource.Battery;
        PowerSource destinationPowerSource = enableFullChargeBeforeTransition
            ? PowerSource.Battery
            : PowerSource.PluggedIn;
        DeviceCapabilities lightingCapabilities = DeviceCapabilities.SafeTargetDefaults() with
        {
            LightingEffects = new HashSet<LightingEffect>
            {
                LightingEffect.Off,
                LightingEffect.Static,
            },
        };
        TestContext context = CreateWritableContext(
            initialPowerSource: initialPowerSource,
            timeProvider: timeProvider,
            userConfigurationRepository: userConfigurationRepository,
            profileValidator: ProfileSetValidator.CreateForLightingCapabilities(
                lightingCapabilities));
        context.Device.Capabilities = context.Device.Capabilities with
        {
            LightingEffects = lightingCapabilities.LightingEffects,
        };
        if (activeUser is not null)
        {
            await context.Runtime.ActivateUserAsync(activeUser, CancellationToken.None);
        }
        PowerProfile destination = (destinationPowerSource == PowerSource.Battery
            ? context.Runtime.GetStatus().Profiles.Battery
            : context.Runtime.GetStatus().Profiles.PluggedIn) with
        {
            Fans = destinationPowerSource == PowerSource.Battery
                ? FanMode.Automatic
                : FanMode.Maximum,
            FanControl = FanControlSettings.FromLegacy(
                destinationPowerSource == PowerSource.Battery
                    ? FanMode.Automatic
                    : FanMode.Maximum),
            BatteryProtectionEnabled = destinationProtectionEnabled,
            Lighting = changeLighting
                ? LightingSettingsFactory.Static(new RgbColor(1, 2, 3), 40)
                : (destinationPowerSource == PowerSource.Battery
                    ? context.Runtime.GetStatus().Profiles.Battery
                    : context.Runtime.GetStatus().Profiles.PluggedIn).Lighting,
        };
        ProfileSet profiles = destinationPowerSource == PowerSource.Battery
            ? context.Runtime.GetStatus().Profiles with { Battery = destination }
            : context.Runtime.GetStatus().Profiles with { PluggedIn = destination };
        ControlOperationResult stored = await context.Runtime.UpdateProfilesAsync(
            profiles,
            CancellationToken.None);
        Assert.True(stored.Status == ControlOperationStatus.Stored, stored.Message);
        if (enableFullChargeBeforeTransition)
        {
            Assert.Equal(
                ControlOperationStatus.Applied,
                (await context.Runtime.SetFullChargeOverrideAsync(true, CancellationToken.None)).Status);
        }

        context.Device.UseScopedPerformanceFanRead = true;
        context.Device.AfterSetter = subsystem =>
        {
            if (subsystem == DeviceSubsystem.Performance)
            {
                // The fake has committed Performance first. Production then
                // loses the combined thermal final-confirmation read inside
                // ProductionBatteryPort, before the aggregate state read.
                throw new BladeWriteException(
                    WriteSubmissionState.Indeterminate,
                    BladeWriteFailurePhase.ThermalFinalConfirmationRead,
                    "Injected acknowledged performance final-read failure.");
            }
        };
        context.Telemetry.Current = CreateTelemetry(destinationPowerSource);

        await context.Runtime.HandlePowerSourceChangedAsync(CancellationToken.None);

        context.Device.AfterSetter = null;
        return context;
    }

    private async Task<TestContext> CreateOwnedStaticLightingContextAsync(
        Func<BatteryConfigurationCommitBoundary, CancellationToken, Task>?
            transactionBoundary = null,
        LowPowerGate? lowPowerGate = null,
        IUserConfigurationRepository? userConfigurationRepository = null,
        bool explicitAction = true,
        IHyperBoostOwnershipJournalStore? hyperBoostOwnershipJournalStore = null)
    {
        LightingSettings lighting = LightingSettingsFactory.Static(
            new RgbColor(0, 128, 255),
            brightness: 60);
        DeviceCapabilities capabilities = DeviceCapabilities.Unavailable() with
        {
            LightingEffects = new HashSet<LightingEffect>
            {
                LightingEffect.Off,
                LightingEffect.Static,
            },
        };
        TestContext context = CreateContext(
            providerAvailable: true,
            profileValidator: ProfileSetValidator.CreateForLightingCapabilities(capabilities),
            transactionBoundary: transactionBoundary,
            lowPowerGate: lowPowerGate,
            userConfigurationRepository: userConfigurationRepository,
            hyperBoostOwnershipJournalStore: hyperBoostOwnershipJournalStore);
        context.Device.Capabilities = DeviceCapabilities.SafeTargetDefaults() with
        {
            LightingEffects = capabilities.LightingEffects,
        };
        context.Device.ConfirmedState = new ConfirmedDeviceState(
            PerformancePreset.Balanced,
            FanMode.Automatic,
            ConfirmedBattery(80),
            null);
        await context.Runtime.ObserveAsync(CancellationToken.None);

        ControlOperationResult applied = await context.Runtime.SetLightingOverrideAsync(
            new ManualOverride<LightingSettings>(
                lighting,
                OverrideLifetime.UntilPowerSourceChange),
            CancellationToken.None);
        if (!explicitAction)
        {
            typeof(ServiceControlRuntime)
                .GetField(
                    "explicitLightingOwnershipActive",
                    System.Reflection.BindingFlags.Instance
                        | System.Reflection.BindingFlags.NonPublic)!
                .SetValue(context.Runtime, false);
        }

        Assert.Equal(ControlOperationStatus.Applied, applied.Status);
        Assert.Equal(1, context.Device.LightingSetCalls);
        Assert.Equal(
            LightingRendererOwnershipState.Static,
            context.Runtime.GetStatus().LightingRendererOwnership);
        return context;
    }

    private async Task<TestContext> CreateLightingTransitionContextAsync(
        LightingRendererOwnershipState ownership,
        PowerSource initialPowerSource = PowerSource.PluggedIn,
        Func<TimeSpan, CancellationToken, Task>? transitionRetryDelay = null,
        LogoLightingMode? logoMode = null)
    {
        LightingSettings pluggedInLighting = LightingSettingsFactory.Static(
            new RgbColor(255, 64, 0),
            brightness: 60) with
        {
            LogoMode = logoMode,
        };
        LightingSettings batteryLighting = LightingSettingsFactory.Static(
            new RgbColor(0, 96, 255),
            brightness: 40) with
        {
            LogoMode = logoMode,
        };
        LightingSettings usbCLighting = LightingSettingsFactory.Static(
            new RgbColor(128, 0, 255),
            brightness: 30) with
        {
            LogoMode = logoMode,
        };
        DeviceCapabilities lightingCapabilities = DeviceCapabilities.Unavailable() with
        {
            LightingEffects = new HashSet<LightingEffect>
            {
                LightingEffect.Off,
                LightingEffect.Static,
            },
            LogoLightingModes = logoMode is { } configuredLogoMode
                ? new HashSet<LogoLightingMode>
                {
                    configuredLogoMode,
                    LogoLightingMode.Off,
                }
                : new HashSet<LogoLightingMode>(),
        };
        TestContext context = CreateContext(
            providerAvailable: true,
            initialPowerSource: initialPowerSource,
            transitionRetryDelay: transitionRetryDelay,
            profileValidator: ProfileSetValidator.CreateForLightingCapabilities(
                lightingCapabilities));
        context.Device.Capabilities = DeviceCapabilities.SafeTargetDefaults() with
        {
            LightingEffects = lightingCapabilities.LightingEffects,
            LogoLightingModes = lightingCapabilities.LogoLightingModes,
        };
        ProfileSet profiles = context.Runtime.GetStatus().Profiles;
        profiles = profiles with
        {
            PluggedIn = profiles.PluggedIn with { Lighting = pluggedInLighting },
            Battery = profiles.Battery with { Lighting = batteryLighting },
            UsbC = profiles.UsbC with { Lighting = usbCLighting },
        };
        await context.Runtime.UpdateProfilesAsync(profiles, CancellationToken.None);
        PowerProfile active = initialPowerSource == PowerSource.Battery
            ? profiles.Battery
            : profiles.PluggedIn;
        context.Device.ConfirmedState = new ConfirmedDeviceState(
            active.Performance,
            active.Fans,
            ConfirmedBattery(80),
            active.Lighting)
        {
            LogoLighting = active.Lighting.LogoMode,
        };
        context.Device.LightingRendererOwnership = ownership;
        await context.Runtime.ObserveAsync(CancellationToken.None);
        if (ownership == LightingRendererOwnershipState.Static)
        {
            ControlOperationResult owned = await context.Runtime.SetLightingOverrideAsync(
                new ManualOverride<LightingSettings>(
                    active.Lighting,
                    OverrideLifetime.UntilPowerSourceChange),
                CancellationToken.None);
            Assert.Equal(ControlOperationStatus.Applied, owned.Status);
        }
        Assert.Empty(context.Runtime.GetStatus().ExternalChanges);
        Assert.Equal(ownership, context.Runtime.GetStatus().LightingRendererOwnership);
        return context;
    }

    private async Task<TestContext> CreateBatteryBalancedTransitionContextAsync(
        PowerSource initialSource,
        PerformancePreset initialPerformance)
    {
        TestContext context = CreateContext(
