                    == FanMode.Automatic
                        ? context.Device.ConfirmedState with
                        {
                            Performance = PerformancePreset.Balanced,
                        }
                        : context.Device.ConfirmedState with
                        {
                            Performance = null,
                            Fans = FanMode.Maximum,
                        };
            }
        };
        var fanControl = new FanControlSettings(
            FanMode.Fixed,
