    private sealed class RecordingHyperBoostOwnershipJournalStore
        : IHyperBoostOwnershipJournalStore
    {
        public HyperBoostOwnershipJournal? Journal { get; set; }

        public bool FailLoad { get; set; }

        public int LoadCalls { get; private set; }

        public Action<int>? BeforeLoadResult { get; set; }

        public bool AllowsExplicitRecoveryBaselineCapture { get; set; }

        public bool FailWrite { get; set; }

        public int? FailWriteOnCall { get; set; }

        public Action? AfterWriteFailure { get; set; }

        public int WriteCalls { get; private set; }

        public bool FailClear { get; set; }

        public Action? BeforeConditionalReplace { get; set; }

        public Action? BeforeConditionalClear { get; set; }

        public string? JournalSha256Override { get; set; }

        public List<HyperBoostOwnershipJournal> Writes { get; } = [];

        private string? JournalSha256 => Journal is null
            ? null
            : JournalSha256Override
                ?? Convert.ToHexString(SHA256.HashData(
                    JsonSerializer.SerializeToUtf8Bytes(Journal)));

        public Task<HyperBoostOwnershipJournalLoadResult> LoadAsync(
            CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            LoadCalls++;
            BeforeLoadResult?.Invoke(LoadCalls);
            cancellationToken.ThrowIfCancellationRequested();
            return FailLoad
                ? Task.FromException<HyperBoostOwnershipJournalLoadResult>(
                    new IOException("journal load failed"))
                : Task.FromResult(new HyperBoostOwnershipJournalLoadResult(
                    Journal,
                    Invalid: false,
                    AllowsExplicitRecoveryBaselineCapture:
                        AllowsExplicitRecoveryBaselineCapture,
                    Sha256: JournalSha256));
        }

        public Task<string?> WriteAsync(
            HyperBoostOwnershipJournal journal,
            CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (!journal.IsWellFormed)
            {
                throw new ArgumentException(
                    "The HyperBoost ownership journal is invalid.",
                    nameof(journal));
            }

            WriteCalls++;
            if (FailWrite || WriteCalls == FailWriteOnCall)
            {
                AfterWriteFailure?.Invoke();
                return Task.FromException<string?>(
                    new IOException("journal write failed"));
            }

            Journal = journal;
            Writes.Add(journal);
            return Task.FromResult(JournalSha256);
        }

        public Task<HyperBoostOwnershipJournalMutationResult> TryReplaceAsync(
            HyperBoostOwnershipJournal expectedJournal,
            string? expectedSha256,
            HyperBoostOwnershipJournal replacementJournal,
            CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            BeforeConditionalReplace?.Invoke();
            if (Journal != expectedJournal
                || expectedSha256 is null
                || !StringComparer.Ordinal.Equals(
                    expectedSha256,
                    JournalSha256))
            {
                return Task.FromResult(
                    new HyperBoostOwnershipJournalMutationResult(false));
            }

            WriteCalls++;
            if (FailWrite || WriteCalls == FailWriteOnCall)
            {
                AfterWriteFailure?.Invoke();
                return Task.FromException<HyperBoostOwnershipJournalMutationResult>(
                    new IOException("journal write failed"));
            }

            Journal = replacementJournal;
            Writes.Add(replacementJournal);
            return Task.FromResult(
                new HyperBoostOwnershipJournalMutationResult(
                    true,
                    JournalSha256));
        }

        public Task<bool> TryClearAsync(
            HyperBoostOwnershipJournal expectedJournal,
            string? expectedSha256,
            CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            BeforeConditionalClear?.Invoke();
            if (Journal != expectedJournal
                || expectedSha256 is null
                || !StringComparer.Ordinal.Equals(
                    expectedSha256,
                    JournalSha256))
            {
                return Task.FromResult(false);
            }
            if (FailClear)
            {
                return Task.FromException<bool>(
                    new IOException("journal clear failed"));
            }

            Journal = null;
            return Task.FromResult(true);
        }

        public Task ClearAsync(CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (FailClear)
            {
                return Task.FromException(new IOException("journal clear failed"));
            }

            Journal = null;
            return Task.CompletedTask;
        }
    }

