        public Task<DeviceCapabilities> ReadCapabilitiesAsync(CancellationToken cancellationToken)
        {
            TotalCalls++;
            CapabilitiesReadCalls++;
            return Task.FromResult(Capabilities);
        }

        public Task<ConfirmedDeviceState> ReadStateAsync(CancellationToken cancellationToken)
        {
            TotalCalls++;
            StateReadCalls++;
            PowerTransitionReadCalls.Add("State");
            if (pendingReadStateFailureAfterLightingSet)
            {
                pendingReadStateFailureAfterLightingSet = false;
                throw ReadStateFailureAfterLightingSet
                    ?? new IOException("readback failed");
            }
            if (ReadStateFailure is not null
                || ReadStateFailureOnCall == StateReadCalls)
            {
                throw ReadStateFailure
                    ?? ReadStateFailureOnCallException
                    ?? new IOException("readback failed");
            }

            AfterReadState?.Invoke();
            AfterReadStateCall?.Invoke(StateReadCalls);
            return Task.FromResult(ConfirmedState);
        }

        public Task<ConfirmedDeviceState> ReadPerformanceFanStateAsync(
            CancellationToken cancellationToken)
        {
            if (!UseScopedPerformanceFanRead)
            {
                return ReadStateAsync(cancellationToken);
            }

            cancellationToken.ThrowIfCancellationRequested();
            TotalCalls++;
            PerformanceFanStateReadCalls++;
            BeforePerformanceFanStateReadResult?.Invoke(
                PerformanceFanStateReadCalls);
            cancellationToken.ThrowIfCancellationRequested();
            if (PerformanceFanStateReadFailureOnCall
                    == PerformanceFanStateReadCalls
                || PerformanceFanStateReadFailureCalls.Contains(
                    PerformanceFanStateReadCalls))
            {
                throw PerformanceFanStateReadFailureOnCallException
                    ?? new IOException("scoped thermal readback failed");
            }

            return Task.FromResult(new ConfirmedDeviceState(
                ConfirmedState.Performance,
                ConfirmedState.Fans,
                Battery: null,
                Lighting: null)
            {
                HyperBoostActive = ConfirmedState.HyperBoostActive,
                CustomPerformance = ConfirmedState.CustomPerformance,
                GpuClockOffsets = ConfirmedState.GpuClockOffsets,
            });
        }

        public Task<ConfirmedDeviceState> ReadLightingStateAsync(
            CancellationToken cancellationToken)
        {
            if (ScopedLightingReadback is null)
            {
                return ReadStateAsync(cancellationToken);
            }

            BeforeReadLightingState?.Invoke();
            cancellationToken.ThrowIfCancellationRequested();
            TotalCalls++;
            return Task.FromResult(ScopedLightingReadback);
        }

        public async Task<PowerTransitionDeviceStateReadResult>
            ReadStateForPowerTransitionAsync(CancellationToken cancellationToken)
        {
            PowerTransitionStateReadCalls++;
            if (PowerTransitionStateReads.TryDequeue(
                out PowerTransitionDeviceStateReadResult scripted))
            {
                cancellationToken.ThrowIfCancellationRequested();
                TotalCalls++;
                StateReadCalls++;
                PowerTransitionReadCalls.Add("TransitionState");
                return scripted;
            }
            ConfirmedDeviceState state = await ReadStateAsync(cancellationToken);
            return new(
                state,
                LightingOffConfirmationUnavailable: false);
        }

        public Task<FanRpmReadings?> ReadFanRpmAsync(CancellationToken cancellationToken)
        {
            TotalCalls++;
            FanRpmReadCalls++;
            return FanRpmFailure is null
                ? Task.FromResult(
                    FanReadings ?? (FanRpm.HasValue
                        ? new FanRpmReadings(FanRpm.Value, FanRpm.Value)
                        : null))
                : Task.FromException<FanRpmReadings?>(FanRpmFailure);
        }

        public Task<AdapterPowerState> ReadAdapterPowerStateAsync(
            CancellationToken cancellationToken)
        {
            TotalCalls++;
            AdapterPowerReadCalls++;
            if (AdapterPowerFailures.TryDequeue(out Exception? scriptedFailure)
                && scriptedFailure is not null)
            {
                return Task.FromException<AdapterPowerState>(scriptedFailure);
            }

            if (AdapterPowerFailure is not null)
            {
                return Task.FromException<AdapterPowerState>(AdapterPowerFailure);
            }

            return Task.FromResult(
                AdapterPowerStates.Count > 0
                    ? AdapterPowerStates.Dequeue()
                    : AdapterPowerState);
        }

        public Task<string?> ReadMcuVersionAsync(CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            McuVersionReadCalls++;
            if (McuVersionFailures.TryDequeue(out Exception? failure))
            {
                return Task.FromException<string?>(failure);
            }

            string? version = McuVersion;
            AfterMcuVersionRead?.Invoke();
            if (version is null)
            {
                return Task.FromResult<string?>(null);
            }

            TotalCalls++;
            return Task.FromResult<string?>(version);
        }

        public Task<Rz090581CapabilityDiagnostics?>
            ReadRz090581CapabilityDiagnosticsAsync(
                CancellationToken cancellationToken)
        {
            Rz090581CapabilityDiagnosticsReadCalls++;
            BeforeRz090581CapabilityDiagnosticsRead?.Invoke();
            cancellationToken.ThrowIfCancellationRequested();
            if (Rz090581CapabilityDiagnosticsFailures.TryDequeue(out Exception? failure)
                || (failure = Rz090581CapabilityDiagnosticsFailure) is not null)
            {
                return Task.FromException<Rz090581CapabilityDiagnostics?>(failure);
            }

            AfterRz090581CapabilityDiagnosticsRead?.Invoke();
            return Task.FromResult(Rz090581CapabilityDiagnostics);
        }

