        public Task SetPerformanceAsync(PerformancePreset value, CancellationToken cancellationToken)
        {
            TotalCalls++;
            PerformanceSetCalls++;
            PerformanceWrites.Add(value);
            if (PerformanceFailures.TryDequeue(out Exception? queuedFailure))
            {
                if (MutatePerformanceBeforeQueuedFailure)
                {
                    ConfirmedState = ConfirmedState with
                    {
                        Performance = value,
                        CustomPerformance = null,
                    };
                }
                BeforeQueuedPerformanceFailure?.Invoke();
                throw queuedFailure;
            }
            if (PerformanceFailure is not null)
            {
                throw PerformanceFailure;
            }

            if (SuppressConfirmationFor != DeviceSubsystem.Performance)
            {
                ConfirmedState = ConfirmedState with { Performance = value };
            }

            AfterSetter?.Invoke(DeviceSubsystem.Performance);
            return Task.CompletedTask;
        }

        public Task SetHyperBoostAsync(
            bool enabled,
            PerformancePreset baseMode,
            CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            TotalCalls++;
            HyperBoostSetCalls++;
            if (enabled)
            {
                HyperBoostEntryStates.Add((
                    ConfirmedState.Performance,
                    ConfirmedState.Fans));
            }
            if (SuppressHyperBoostMutation)
            {
                return Task.CompletedTask;
            }
            if (HyperBoostFailures.TryDequeue(out Exception? failure))
            {
                AfterHyperBoostFailure?.Invoke();
                return Task.FromException(failure);
            }
            ConfirmedState = enabled
                ? ConfirmedState with
                {
                    Performance = null,
                    Fans = FanMode.Automatic,
                    HyperBoostActive = true,
                }
                : ConfirmedState with
                {
                    Performance = baseMode,
                    Fans = FanMode.Automatic,
                    HyperBoostActive = false,
                };
            return Task.CompletedTask;
        }

        Task ISingleAttemptThermalDevice.SetHyperBoostOnceAsync(
            bool enabled,
            PerformancePreset baseMode,
            CancellationToken cancellationToken) => SetHyperBoostAsync(
                enabled,
                baseMode,
                cancellationToken);

