        public Task SetFanTargetsAsync(
            int fan1Rpm,
            int fan2Rpm,
            CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (!FanTargetsAvailable)
            {
                return Task.FromException(
                    new CapabilityUnavailableException(
                        "Manual fan targets are unavailable in this test device."));
            }

            TotalCalls++;
            FanSetCalls++;
            int maximumRpm = Capabilities.FanSpeedRange?.MaximumRpm
                ?? FanControlSettings.MaximumSpeedRpm;
            FanTargets.Add(new FanTargetSpeeds(
                fan1Rpm,
                fan2Rpm,
                fan1Rpm == maximumRpm
                    && fan2Rpm == maximumRpm));
            if (FanTargetFailures.TryDequeue(out Exception? failure))
            {
                throw failure;
            }
            ConfirmedState = ConfirmedState with { Fans = FanMode.Maximum };
            AfterSetter?.Invoke(DeviceSubsystem.Fans);
            return Task.CompletedTask;
        }

        Task ISingleAttemptThermalDevice.SetFanTargetsOnceAsync(
            int fan1Rpm,
            int fan2Rpm,
            CancellationToken cancellationToken) =>
            SetFanTargetsAsync(fan1Rpm, fan2Rpm, cancellationToken);

        Task ISingleAttemptThermalDevice
            .ContinueFanTargetsAfterManualEntryOnceAsync(
            int fan1Rpm,
            int fan2Rpm,
            CancellationToken cancellationToken) =>
            SetFanTargetsAsync(fan1Rpm, fan2Rpm, cancellationToken);

