            BeforeLightingRefreshRateSet?.Invoke();
            cancellationToken.ThrowIfCancellationRequested();
            if (LightingRefreshRateFailure is not null)
            {
                throw LightingRefreshRateFailure;
            }

            return Task.CompletedTask;
        }

